function validate([data]) {
  if (!Array.isArray(data) || data.length < 1 || data.length > 100000) return 'data needs 1 to 100000 entries.';
  if (data.some(v => v !== 0 && v !== 1)) return 'Every entry of data is 0 or 1.';
  return null;
}

