function minSwaps(data) {
  let ones = 0;
  for (const bit of data) {
    ones += bit;
  }

  let inWindow = 0;
  let most = 0;
  for (let right = 0; right < data.length; right++) {
    inWindow += data[right];
    if (right >= ones) {
      inWindow -= data[right - ones];
    }
    most = Math.max(most, inWindow);
  }
  return ones - most;
}

