function minSwaps(data) {
  const n = data.length;
  const total = data.filter(v => v === 1).length;
  let answer = Infinity;
  // Try every place for the final block of 1s and count the 0s it would have to evict.
  for (let start = 0; start + total <= n; start++) {
    let zeros = 0;
    for (let k = start; k < start + total; k++) if (data[k] === 0) zeros++;
    answer = Math.min(answer, zeros);
  }
  return answer;
}

