function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 12);
  const mode = rand();
  const density = mode < 0.15 ? 0 : mode < 0.3 ? 1 : rand();
  const data = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  // Sometimes plant a dense stretch so the best window is not uniform noise.
  if (rand() < 0.5 && n > 2) {
    const start = Math.floor(rand() * n);
    const len = 1 + Math.floor(rand() * Math.max(1, Math.floor(n / 3)));
    for (let k = start; k < Math.min(n, start + len); k++) if (rand() < 0.85) data[k] = 1;
  }
  return [data];
}
